#include <print>
#include <vector>

int main() {
    int target = 8;
    std::vector<int> coins = {1, 3, 4, 5};
    std::vector<int> dp(target + 1, 1000);
    dp[0] = 0;
    for (int c : coins)
        for (int j = c; j <= target; ++j)
            if (dp[j - c] + 1 < dp[j]) dp[j] = dp[j - c] + 1;
    std::println("凑 {} 元最少 {} 枚", target, dp[target]);
    std::vector<int> cnt(target + 1, 0);
    cnt[0] = 1;
    for (int c : coins)
        for (int j = c; j <= target; ++j)
            cnt[j] += cnt[j - c];
    std::println("凑 8 元有 {} 种凑法", cnt[target]);
    return 0;
}

